// Get all available tables most recent logs
let Tab1 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table = tostring(tablename)
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
// Get all vendors and products within common security logs most recent log
let Tab2 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table_ = tostring(tablename)
    | where Table_ == "CommonSecurityLog"
    | as cache
    | extend Table = DeviceVendor
    | union (cache | extend Table = DeviceProduct)
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
// Get all products from within SecurityAlerts most recent log
let Tab3 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table_ = tostring(tablename)
    | where Table_ == "SecurityAlert"
    | extend Table = ProductName
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
// Get all products from within ASimTables most recent log
let Tab4 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table_ = tostring(tablename)
    | where Table_ has_any ("ASimNetworkSessionLogs", "ASimDnsActivityLogs")
    | extend Table = EventProduct
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
let MergedTables = union Tab1, Tab2, Tab3, Tab4;
