| join kind=inner (MonitoredAssets) on Table
| where tolower(Maintenance) !~ "true"
| extend timenow = now()
| extend time_diff = datetime_diff("minute", timenow, Last_seen)
| extend OverTimeDiff = case(
    Frequency == "Moderate", 180,
    Frequency == "Medium", 360,
    Frequency == "Low", 720,
    Frequency == "VeryLow", 1440,
    Frequency == "Lowest", 4320,
    Frequency == "Weekly", 10080,
    0
)
| extend OverdueByMinutes = time_diff - OverTimeDiff
| where OverdueByMinutes >= 0
